// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: playfairFamily } = loadPlayfair();



export type PopcornTextProps = Record<string, any>;

const EMOJIS = ['🤯', '🥟', '🍲', '🍜', '🍚', '🏮', '🥬'];

const PopcornText: React.FC<PopcornTextProps> = ({
  text = "FAVOURITE",
  primaryColor = "#FFD700", // Popcorn Golden Yellow
  secondaryColor = "#FFFFFF", // Popcorn White
  backgroundColor = "#E23D28", // Classic Popcorn Bucket Red
  transparentBackground = false,
  durationInSeconds = 5,
  fontSize = 120,
  quirkiness = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Calculate subtle zoom scaling for the whole container over the animation duration
  const totalFrames = durationInSeconds * fps;
  const containerScale = interpolate(frame, [0, totalFrames], [1, 1.15], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      <div 
        style={{ 
          position: "absolute", 
          width: "100%", 
          height: "100%", 
          transform: `scale(${containerScale})`, // Slow subtle zoom applied to both text and emojis
          transition: "none" 
        }}
      >
        {/* Sprinkled Emojis - Exactly one of each */}
        {EMOJIS.map((emoji, i) => {
          // Spread pops throughout the text pop duration
          const maxBaseDelay = text.length * 2;
          const baseDelay = random(`emoji-delay-${i}`) * (maxBaseDelay + 10);
          const emojiFrame = frame - baseDelay;
          
          // Balanced 360-degree distribution to prevent lopsidedness
          // Divide the circle evenly among the emojis
          const baseAngle = (i / EMOJIS.length) * (Math.PI * 2);
          // Add a little noise to avoid perfectly rigid geometric placement
          const angle = baseAngle + (random(`emoji-angle-jitter-${i}`) - 0.5) * 0.6;
          
          // Determine radius/spread from center
          const rx = 28 + random(`emoji-rx-${i}`) * 15; // horizontal spread from center
          const ry = 22 + random(`emoji-ry-${i}`) * 15; // vertical spread from center
          
          const posX = 50 + Math.cos(angle) * rx;
          const posY = 50 + Math.sin(angle) * ry;

          // Parabolic jump logic for emojis
          const jumpProgress = interpolate(emojiFrame, [0, 30], [0, Math.PI], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const jumpHeight = 100 + random(`emoji-jump-${i}`) * 200 * quirkiness;
          const yOffset = Math.sin(jumpProgress) * -jumpHeight;

          // Bouncy expansion
          const emojiScale = spring({
            frame: emojiFrame,
            fps,
            config: { mass: 0.5, damping: 5, stiffness: 200 }
          });

          const rot = (random(`emoji-rot-${i}`) - 0.5) * 80 + interpolate(emojiFrame, [0, 40], [0, (random(`emoji-spin-${i}`) - 0.5) * 90], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          // Varying sizes
          const eSize = fontSize * (0.6 + random(`emoji-size-${i}`) * 0.8);

          return (
            <div
              key={`emoji-${i}`}
              style={{
                position: "absolute",
                left: `${posX}%`,
                top: `${posY}%`,
                fontSize: eSize,
                transform: `translate(-50%, -50%) translateY(${yOffset}px) scale(${Math.max(0, emojiScale)}) rotate(${rot}deg)`,
                zIndex: 0,
                transition: "none",
                lineHeight: 1,
              }}
            >
              {emoji}
            </div>
          );
        })}

        {/* Main Text Container */}
        <AbsoluteFill style={{ justifyContent: "center", alignItems: "center", zIndex: 1 }}>
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              flexWrap: "wrap",
              justifyContent: "center",
              alignItems: "center",
              width: "85%", // Keeps text within safe zones, wraps gracefully for longer text
              gap: "20px", // Increased letter spacing
              transition: "none",
            }}
          >
            {text.split("").map((char, i) => {
              const isSpace = char === " ";
              const color = i % 2 === 0 ? primaryColor : secondaryColor;
              
              // Non-chronological popcorn popping timing: Randomize pop order independent of index
              const maxBaseDelay = text.length * 2;
              const baseDelay = random(`pop-order-${i}`) * maxBaseDelay;
              const randomExtra = random(`delay-${i}`) * 6 * quirkiness;
              const delay = baseDelay + randomExtra;
              const charFrame = frame - delay;

              // Parabolic jump logic using Sine wave (0 -> Math.PI creates a perfect up-and-down arc)
              const jumpProgress = interpolate(charFrame, [0, 25], [0, Math.PI], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });
              const jumpHeight = 100 + random(`jump-${i}`) * 150 * quirkiness;
              const yOffset = Math.sin(jumpProgress) * -jumpHeight;

              // Random static offsets based on quirkiness parameter
              let finalRot = (random(`rot-${i}`) - 0.5) * 40 * quirkiness;
              const baseY = (random(`baseY-${i}`) - 0.5) * 60 * quirkiness;

              // Wiggle logic for letters 'F' and 'I' after all letters pop
              const upperChar = char.toUpperCase();
              const isWiggleTarget = upperChar === "F" || upperChar === "I";
              const wiggleStartFrame = maxBaseDelay + (6 * quirkiness) + 30; // Start safely after max possible pop delay
              
              if (isWiggleTarget) {
                const wiggleAmplitude = interpolate(frame, [wiggleStartFrame, wiggleStartFrame + 15], [0, 10], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                });
                // Wiggle rotation added to the final static rotation
                finalRot += Math.sin((frame - wiggleStartFrame) * 0.5) * wiggleAmplitude;
              }

              // Bouncy expansion
              const scale = spring({
                frame: charFrame,
                fps,
                config: { mass: 0.4, damping: 6, stiffness: 250 },
              });

              // Crumb/Spark effect radiating from the popping letter
              const sparks = isSpace ? null : Array.from({ length: 5 }).map((_, sparkIdx) => {
                const angle = (sparkIdx / 5) * Math.PI * 2 + random(`sparkAngle-${i}-${sparkIdx}`);
                const sparkDistance = interpolate(charFrame, [0, 15], [0, fontSize * 1.2], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                });
                const sparkOpacity = interpolate(charFrame, [0, 5, 15], [0, 1, 0], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                });
                const sparkScale = interpolate(charFrame, [0, 15], [1, 0], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                });
                const sparkX = Math.cos(angle) * sparkDistance;
                const sparkY = Math.sin(angle) * sparkDistance;

                return (
                  <div
                    key={sparkIdx}
                    style={{
                      position: "absolute",
                      width: fontSize * 0.15,
                      height: fontSize * 0.15,
                      backgroundColor: color,
                      borderRadius: "50%",
                      top: "50%",
                      left: "50%",
                      transform: `translate(-50%, -50%) translate(${sparkX}px, ${sparkY}px) scale(${sparkScale})`,
                      opacity: sparkOpacity,
                      transition: "none",
                    }}
                  />
                );
              });

              return (
                <div
                  key={i}
                  style={{
                    position: "relative",
                    display: "inline-block",
                    transform: `translateY(${baseY + yOffset}px) scale(${Math.max(0, scale)}) rotate(${finalRot}deg)`,
                    transition: "none",
                  }}
                >
                  {sparks}
                  <span
                    style={{
                      display: "inline-block",
                      color,
                      fontSize,
                      fontWeight: 400,
                      fontFamily: playfairFamily,
                      textTransform: "uppercase",
                      textShadow: "6px 6px 0px rgba(0,0,0,0.25)",
                      lineHeight: 1.1,
                      transition: "none",
                    }}
                  >
                    {isSpace ? "\u00A0" : char}
                  </span>
                </div>
              );
            })}
          </div>
        </AbsoluteFill>
      </div>
    </AbsoluteFill>
  );
};

export default PopcornText;